function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(45, 50) : int(3, 8);
  const top = size === 'large' ? 100 : [n, 12, 100][int(0, 2)];
  const pool = Array.from({ length: top }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const nums = pool.slice(0, n);
  const shape = int(0, 4);
  if (shape === 0) nums.sort((a, b) => a - b);
  if (shape === 1) nums.sort((a, b) => b - a);
  return [nums];
}
